/* Google Maps JavaScript API. All TTSpot listings here are explicitly fictional prelaunch examples. */
(()=>{
const regions={kl:{name:'KL / Selangor',center:[101.65,3.12],zoom:10.4},johor:{name:'Johor',center:[103.75,1.50],zoom:11.1},penang:{name:'Penang',center:[100.31,5.40],zoom:11.1}};
const spots=[
 ['kl','meets',101.636,3.11,'PJ night TT','Sample meet · Petaling Jaya area'],['kl','meets',101.705,3.155,'KL weekend crew','Sample meet · Kuala Lumpur area'],['kl','checkpoints',101.688,3.147,'City photo stop','Sample checkpoint · Kuala Lumpur area'],['kl','checkpoints',101.585,3.073,'Subang lepak stop','Sample checkpoint · Subang Jaya area'],['kl','vendors',101.616,3.102,'Detailing pit stop','Sample vendor · Petaling Jaya area'],['kl','vendors',101.535,3.08,'Workshop discovery','Sample vendor · Shah Alam area'],
 ['johor','meets',103.758,1.49,'JB weekend TT','Sample meet · Johor Bahru area'],['johor','checkpoints',103.724,1.471,'Southern photo stop','Sample checkpoint · Johor Bahru area'],['johor','vendors',103.777,1.529,'Johor car-care stop','Sample vendor · Johor Bahru area'],
 ['penang','meets',100.317,5.418,'Penang kaki kereta','Sample meet · George Town area'],['penang','checkpoints',100.332,5.403,'Island photo stop','Sample checkpoint · George Town area'],['penang','vendors',100.299,5.365,'Island car-care stop','Sample vendor · Penang area']
];
let map,region='kl',category='all',markers=[],loaded=false,timeout,loading=false,authFailed=false,popup;
const world=document.createElement('div');world.className='tt-map-world';world.innerHTML='<div class="tt-map-canvas" aria-label="Interactive TTSpot map"></div><div class="tt-map-badge">TTSPOT · DEMO SPOTS</div><button class="tt-map-expand" type="button">Explore map ↗</button><div class="tt-map-status" role="status">Loading map…</div>';
const dashboard=document.querySelector('#dashboard-map-slot'),full=document.querySelector('#full-map-slot'),status=world.querySelector('.tt-map-status');dashboard.append(world);

function notice(text,retry=false){status.hidden=false;status.textContent=text;if(retry){const b=document.createElement('button');b.textContent='Reload map';b.onclick=()=>location.reload();status.append(b)}}
window.gm_authFailure=()=>{authFailed=true;clearTimeout(timeout);notice('Google Maps authorization failed. Check the website restriction, Maps JavaScript API and billing settings.');};
function fly(){if(!map)return;const r=regions[region],center={lng:r.center[0],lat:r.center[1]};map.setZoom(r.zoom);matchMedia('(prefers-reduced-motion: reduce)').matches?map.setCenter(center):map.panTo(center);}
function paint(){markers.forEach(m=>m.map=null);markers=[];popup?.close();document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===category)));world.querySelector('.tt-map-badge').textContent=regions[region].name.toUpperCase()+' · DEMO SPOTS';if(!map)return;for(const [area,type,lng,lat,title,description] of spots){if(area!==region||(category!=='all'&&type!==category))continue;const el=document.createElement('div');el.className='tt-spot';el.dataset.category=type;el.textContent={meets:'TT',checkpoints:'●',vendors:'V'}[type];const content=document.createElement('div'),heading=document.createElement('strong'),detail=document.createElement('p'),note=document.createElement('p');content.className='tt-google-detail';heading.textContent=title;detail.textContent=description;note.textContent='Prelaunch example only. No confirmed event or partner at this location.';content.append(heading,detail,note);const marker=new google.maps.marker.AdvancedMarkerElement({map,position:{lng,lat},content:el,title:title+' — demo '+type});marker.addListener('click',()=>{popup.setContent(content);popup.open({map,anchor:marker})});markers.push(marker);}}
function resizeMap(){if(map){const center=map.getCenter();google.maps.event.trigger(map,'resize');if(center)map.setCenter(center)}}
function init(){if(map||loading||authFailed)return;loading=true;status.textContent='Loading Google Maps…';status.hidden=false;window.ttspotGoogleReady=()=>{if(authFailed)return;try{const r=regions[region];map=new google.maps.Map(world.querySelector('.tt-map-canvas'),{center:{lng:r.center[0],lat:r.center[1]},zoom:r.zoom,mapId:'DEMO_MAP_ID',colorScheme:google.maps.ColorScheme.DARK,disableDefaultUI:true,zoomControl:true,gestureHandling:'cooperative',scrollwheel:false,clickableIcons:false,keyboardShortcuts:true});popup=new google.maps.InfoWindow({maxWidth:240});google.maps.event.addListenerOnce(map,'tilesloaded',()=>{if(authFailed)return;loaded=true;clearTimeout(timeout);status.hidden=true});paint();new ResizeObserver(resizeMap).observe(world);loading=false}catch(e){loading=false;notice('Google Maps could not start. Please reload.',true)}};
const script=document.createElement('script');const params=new URLSearchParams({key:window.TTSPOT_GOOGLE_MAPS_KEY,v:'weekly',loading:'async',libraries:'marker',callback:'ttspotGoogleReady',language:'en',region:'MY'});script.src='https://maps.googleapis.com/maps/api/js?'+params;script.async=true;script.onerror=()=>{loading=false;clearTimeout(timeout);notice('Google Maps could not connect. Please reload.',true)};document.head.append(script);timeout=setTimeout(()=>{if(!loaded&&!authFailed)notice('Google Maps is taking longer to load.',true)},20000);}
function choose(value,expand=true){if(!['all','meets','checkpoints','vendors'].includes(value))return;category=value;if(expand)openPage('navigation');init();paint();fly()}
const originalOpen=openPage;openPage=function(name){originalOpen(name);if(name==='navigation'||name==='dashboard'){(name==='navigation'?full:dashboard).append(world);init();requestAnimationFrame(resizeMap)}};
world.querySelector('.tt-map-expand').onclick=()=>openPage('navigation');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>choose(b.dataset.filter,false));document.querySelectorAll('[data-map-shortcut]').forEach(b=>b.onclick=()=>choose(b.dataset.mapShortcut));document.querySelector('#map-region').onchange=e=>{if(!regions[e.target.value])return;region=e.target.value;paint();fly()};
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='ttspot-map')choose(e.data.category)});
const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){init();observer.disconnect()}});observer.observe(dashboard);
})();
